class P {
  a = 1;
  #x = 2;
  b = "s";
  get x(): number { return this.#x; }
}
function main(): void {
  const p = new P();
  console.log(p);
  console.log([p]);
  console.log({ p });
  const seen: string[] = [];
  for (const k in p) seen.push(k);
  console.log(seen.join(), Object.keys(p).join(), p.x);
}
